// Merge LinkedIn and Instagram data for the AI agent
const linkedinData = $('Fetch LinkedIn Data').first().json;
const instagramData = $('Fetch Instagram Data').first().json;
const personId = $('Webhook').first().json.body.person_id;

// Get person info
const linkedinRaw = Array.isArray(linkedinData) ? linkedinData[0]?.raw_data : linkedinData?.raw_data;
const instagramRaw = Array.isArray(instagramData) ? instagramData[0]?.raw_data : instagramData?.raw_data;

return {
  json: {
    person_id: personId,
    linkedin: linkedinRaw || {},
    instagram: instagramRaw || {},
    combined_text: `
## LinkedIn Profile
Name: ${linkedinRaw?.full_name || 'Unknown'}
Headline: ${linkedinRaw?.headline || ''}
Summary: ${linkedinRaw?.summary || ''}
Occupation: ${linkedinRaw?.occupation || ''}
Location: ${[linkedinRaw?.city, linkedinRaw?.state, linkedinRaw?.country_full_name].filter(Boolean).join(', ')}
Skills: ${(linkedinRaw?.skills || []).join(', ')}
Experience: ${(linkedinRaw?.experiences || []).map(e => `${e.title} at ${e.company}`).join('; ')}
Education: ${(linkedinRaw?.education || []).map(e => `${e.degree_name} in ${e.field_of_study} at ${e.school}`).join('; ')}
Volunteer: ${(linkedinRaw?.volunteer_work || []).map(v => `${v.title} - ${v.cause}`).join('; ')}
Languages: ${(linkedinRaw?.languages || []).join(', ')}
Certifications: ${(linkedinRaw?.certifications || []).join(', ')}

## Instagram Profile
Username: ${instagramRaw?.username || 'Unknown'}
Bio: ${instagramRaw?.biography || ''}
Followers: ${instagramRaw?.followers_count || 0}
Following: ${instagramRaw?.following_count || 0}
Hashtags Used: ${(instagramRaw?.all_hashtags || []).join(', ')}
Locations Tagged: ${(instagramRaw?.locations || []).join(', ')}
Recent Post Captions: ${instagramRaw?.all_captions || ''}
    `
  }
};

// Parse AI response and prepare for storage
const aiResponse = $input.first().json;
const personId = $('Webhook').first().json.body.person_id;
const linkedinRaw = $('Merge Profile Data').first().json.linkedin;

let analysis;
try {
  // Try to parse if it's a string
  const content = typeof aiResponse.message?.content === 'string' 
    ? aiResponse.message.content 
    : JSON.stringify(aiResponse);
  analysis = JSON.parse(content.replace(/```json\n?|```\n?/g, ''));
} catch (e) {
  analysis = aiResponse;
}

return {
  json: {
    person_id: personId,
    name: analysis.name || linkedinRaw?.full_name || 'Unknown',
    tagline: analysis.tagline || null,
    photo_url: linkedinRaw?.profile_pic_url || null,
    age_estimate: analysis.age_estimate || null,
    location: analysis.location || null,
    occupation: analysis.occupation || null,
    company: analysis.company || null,
    education: analysis.education || null,
    needs: JSON.stringify(analysis.needs || []),
    hobbies: JSON.stringify(analysis.hobbies || []),
    interests: JSON.stringify(analysis.interests || []),
    values: JSON.stringify(analysis.values || []),
    personality: JSON.stringify(analysis.personality || {}),
    communication_style: analysis.communication_style || null,
    energy_level: analysis.energy_level || 'medium',
    lifestyle: analysis.lifestyle || null,
    love_language: analysis.love_language || null,
    summary: analysis.summary || null,
    raw_analysis: JSON.stringify(analysis)
  }
};
